public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    permute(nums, 0, new ArrayList<>(), permutations);

    return permutations;
}

private void permute(int[] nums, int start, List<Integer> current, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        permute(nums, i + 1, current, permutations);
        current.remove(current.size() - 1);
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> remaining = Arrays.asList(nums).subList(0, i).subList(0, nums.length-1);
        List<List<Integer>> permutations = permute(remaining.toArray());
        for (List<Integer> permutation : permutations) {
            permutation.add(0, num);
            result.add(permutation);
        }
    }
    return result;
}

