        int currentNum = nums[i];
        int[] remainingNums = Arrays.copyOf(nums, nums.length - 1);
        remainingNums = Arrays.copyOfRange(remainingNums, 0, i)
                .concat(Arrays.copyOfRange(remainingNums, i + 1, remainingNums.length));
        for (int[] remainingNum : permute(remainingNums)) {
