public int findLargestSubstring(List<String> strings) {
    // Initialize variables to track the largest substring and its length
    String largestSubstring = "";
    int largestSubstringLength = 0;

    // Iterate over each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // Iterate over the characters of the string
        for (int i = 0; i < stringLength; i++) {
            // Get the current character
            char currentChar = string.charAt(i);

            // Check if the character is already part of the largest substring
            if (largestSubstring.contains(currentChar)) {
                // If it is, remove it from the substring
                largestSubstring = largestSubstring.replace(currentChar, '');
            } else {
                // If it's not, add it to the substring
                largestSubstring += currentChar;
            }

            // Update the length of the substring if it's larger than the current largest substring
            int currentSubstringLength = largestSubstring.length();
            if (currentSubstringLength > largestSubstringLength) {
                largestSubstringLength = currentSubstringLength;
            }
        }
    }

    // Return the length of the largest substring
    return largestSubstringLength;
}

