public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

  // Check if the starting and ending n-tersections are valid
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
      end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // Initialize a boolean array to keep track of which n-tersections have been visited
  boolean[] visited = new boolean[n];

  // Add the starting n-tersection to the queue
  Queue<int[]> queue = new LinkedList<>();
  queue.add(start);
  visited[start[0] * n + start[1]] = true;

  // Breadth-first search through the n-teresting space
  while (!queue.isEmpty()) {
    int[] current = queue.remove();

    // If the current n-tersection is the ending n-tersection, return "can be travelled"
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }

    // Add the current n-tersection's neighbors to the queue if they have not been visited
    for (int[] path : paths) {
      int x = current[0] + path[0];
      int y = current[1] + path[1];
      if (x >= 0 && x < n && y >= 0 && y < n && !visited[x * n + y]) {
        queue.add(new int[] { x, y });
        visited[x * n + y] = true;
      }
    }
  }

  // If all n-tersections have been visited and the ending n-tersection has not been reached, return "cannot be travelled"
  return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    // Count the number of common letters
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    // Calculate the approximate value
    double approximateValue = (double) commonLetters / (word1.length() + word2.length());

    // Return the approximate value as a reduced fraction
    return String.format("%d/%d", commonLetters, word1.length() + word2.length());
}

