public int search(int[] nums, int target) {
    // Find the pivot index
    int pivot = findPivot(nums, 0, nums.length - 1);
    if (pivot == -1) {
        // The array is not rotated, so use the standard binary search
        return binarySearch(nums, target, 0, nums.length - 1);
    } else {
        // The array is rotated, so use the two-pointer technique
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}

private int findPivot(int[] nums, int start, int end) {
    if (start > end) {
        return -1;
    }
    int mid = (start + end) / 2;
    if (nums[mid] > nums[start]) {
        return mid;
    } else if (nums[mid] > nums[end]) {
        return findPivot(nums, mid + 1, end);
    } else {
        return findPivot(nums, start, mid - 1);
    }
}

private int binarySearch(int[] nums, int target, int start, int end) {
    if (start > end) {
        return -1;
    }
    int mid = (start + end) / 2;
    if (nums[mid] == target) {
        return mid;
    } else if (nums[mid] < target) {
        return binarySearch(nums, target, mid + 1, end);
    } else {
        return binarySearch(nums, target, start, mid - 1);
    }
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the number of elements to remove from the smallest and largest 5%
    int numElements = arr.length * 5 / 100;

    // Find the index of the smallest and largest elements
    int smallestIndex = arr.length - numElements;
    int largestIndex = numElements;

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = smallestIndex; i < largestIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    double mean = (double) sum / (arr.length - 2 * numElements);

    return mean;
}

