  }
  return sum / (arr.length - 2 * numElements);
}

public double trimMean(int[] arr) {
  // Calculate the median of the array
  double median = median(arr);

  // Calculate the 10% from the left and right of the median
  int left10 = (int) Math.ceil(arr.length * 0.1);
  int right10 = (int) Math.ceil(arr.length * 0.1);

  // Calculate the mean of the elements in the left and right tails
  double leftMean = mean(arr, 0, left10);
  double rightMean = mean(arr, arr.length - right10, arr.length);

  // Calculate the mean of the remaining elements
  double mean = mean(arr, left10, arr.length - right10);

  // Calculate the error between the mean and the median
  double error = Math.abs(mean - median);

  // Return the trimmed mean with an error within 10^-5
  if (error < 0.00001) {
    return mean;
  } else {
    return -1;
  }
}

private double median(int[] arr) {
  int[] sorted = Arrays.copyOf(arr, arr.length);
  Arrays.sort(sorted);
  if (arr.length % 2 == 0) {
    return (sorted[arr.length / 2 - 1] + sorted[arr.length / 2]) / 2;
  } else {
    return sorted[arr.length / 2];
  }
}

private double mean(int[] arr, int start, int end) {
  int sum = 0;
  for (int i = start; i < end; i++) {
    sum += arr[i];
  }
  return (double) sum / (end - start);
}

public double trimMean(int[] arr) {
    int len = arr.length;
    if (len == 0) return 0.0;

    // Calculate the 5% trim points
    int numToRemove = (int) (len * 0.05);
    int[] sortedArr = Arrays.copyOf(arr, len);
    Arrays.sort(sortedArr);
    int firstIdx = numToRemove;
    int lastIdx = len - numToRemove - 1;

    // Calculate the mean of the trimmed array
    double sum = 0.0;
    for (int i = firstIdx; i <= lastIdx; i++) {
        sum += sortedArr[i];
    }
    double mean = sum / (len - 2 * numToRemove);

    // Return the mean with an error of 10^-5
    return Math.round(mean * 100000.0) / 100000.0;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the total length of the array
    int totalLength = arr.length;

    // Calculate the index of the smallest and largest 5% of elements
    int smallestIndex = (int) (totalLength * 0.05);
    int largestIndex = totalLength - smallestIndex;

    // Initialize the sum of the remaining elements
    int sum = 0;

    // Iterate over the remaining elements and add them to the sum
    for (int i = smallestIndex; i < largestIndex; i++) {
        sum += arr[i];
    }

    // Divide the sum by the number of remaining elements to get the mean
    double mean = (double) sum / (totalLength - 2 * smallestIndex);

    // Round the mean to five decimal places
    mean = Math.round(mean * 100000) / 100000;

    return mean;
}

