    Map<Integer, Integer> pairs = new HashMap<>();

    // Initialize a variable to keep track of the number of pairs
    int numPairs = 0;

    // Loop through the array
    for (int i = 0; i < arr.length - 1; i++) {
      // Calculate the sum of the current pair
      int sum = arr[i] + arr[i + 1];

      // If the sum is divisible by k, add the pair to the hash map
      if (sum % k == 0) {
        pairs.put(sum, pairs.getOrDefault(sum, 0) + 1);
        numPairs++;
      }
    }

    // Return true if the number of pairs is equal to n/2
    return numPairs == arr.length / 2;
  }

