public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] dist = new int[n];
  int[] time = new int[n];
  for (int i = 0; i < n; i++) {
    dist[i] = -1;
    time[i] = -1;
  }
  dist[0] = 0;
  time[0] = 0;
  boolean[] visited = new boolean[n];
  for (int i = 0; i < n; i++) {
    visited[i] = false;
  }
  int current = 0;
  int answer = 0;
  while (current != -1) {
    visited[current] = true;
    for (int i = 0; i < edges[current].length; i++) {
      int neighbor = edges[current][i];
      if (hasApple[neighbor]) {
        if (dist[neighbor] == -1 || dist[neighbor] > dist[current] + 1) {
          dist[neighbor] = dist[current] + 1;
          time[neighbor] = time[current] + 1;
        }
      }
    }
    current = -1;
    for (int i = 0; i < n; i++) {
      if (!visited[i]) {
        current = i;
        break;
      }
    }
  }
  for (int i = 0; i < n; i++) {
    if (hasApple[i] && dist[i] != -1) {
      answer = Math.max(answer, dist[i]);
    }
  }
  return answer == 0 ? 0 : answer + time[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] time = new int[n];
    for (int i = 0; i < n; i++) {
        time[i] = -1;
    }
    time[0] = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            return i;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (hasApple[j] && time[j] != -1 && time[j] + 1 < time[i]) {
                time[i] = time[j] + 1;
            }
        }
    }
    return time[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Create a graph from the edge list
  Map<Integer, List<Integer>> graph = new HashMap<>();
  for (int[] edge : edges) {
    int src = edge[0];
    int dst = edge[1];
    if (!graph.containsKey(src)) {
      graph.put(src, new ArrayList<>());
    }
    if (!graph.containsKey(dst)) {
      graph.put(dst, new ArrayList<>());
    }
    graph.get(src).add(dst);
    graph.get(dst).add(src);
  }

  // Initialize a queue for BFS
  Queue<Integer> queue = new LinkedList<>();

  // Initialize a distance map and a visited map
  int[] distance = new int[n];
  boolean[] visited = new boolean[n];
  for (int i = 0; i < n; i++) {
    distance[i] = -1;
    visited[i] = false;
  }

  // BFS from node 0
  queue.add(0);
  distance[0] = 0;
  while (!queue.isEmpty()) {
    int curr = queue.remove();
    for (int neighbor : graph.get(curr)) {
      if (!visited[neighbor]) {
        visited[neighbor] = true;
        distance[neighbor] = distance[curr] + 1;
        queue.add(neighbor);
      }
    }
  }

  // Find the minimum time to collect all apples
  int time = 0;
  for (int i = 0; i < n; i++) {
    if (hasApple[i] && distance[i] != -1) {
      time = Math.max(time, distance[i]);
    }
  }

  return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a distance array to store the minimum time required to reach each node from node 0
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) dist[i] = Integer.MAX_VALUE;

    // Set the distance of node 0 to 0
    dist[0] = 0;

    // Create a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node and its distance
        int node = queue.poll();
        int distance = dist[node];

        // Loop through the neighbors of the current node
        for (int i = 0; i < edges[node].length; i++) {
            // Get the neighbor and its distance
            int neighbor = edges[node][i];
            int neighborDistance = distance + (hasApple[neighbor] ? 1 : 0);

            // If the neighbor has not been visited before, or the current distance is shorter than the previous distance, update the distance and add the neighbor to the queue
            if (dist[neighbor] > neighborDistance) {
                dist[neighbor] = neighborDistance;
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum distance required to collect all the apples and return to node 0
    return dist[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize distances and visited array
    int[] distances = new int[n];
    boolean[] visited = new boolean[n];

    // Set distance of node 0 to 0 and mark it as visited
    distances[0] = 0;
    visited[0] = true;

    // BFS to find distances to all nodes
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int src = edge[0];
            int dest = edge[1];
            if (visited[src] && !visited[dest]) {
                distances[dest] = distances[src] + 1;
                visited[dest] = true;
            }
        }
    }

    // Find min time to collect all apples
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distances[i] > 0) {
            minTime = Math.max(minTime, distances[i]);
        }
    }

    return minTime;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    int len = s.length();
    char[] chars = s.toCharArray();
    int start = 0;
    int end = len - 1;

    StringBuilder sb = new StringBuilder();

    while (start <= end) {
        char smallest = chars[start];
        char largest = chars[end];

        while (start < len && chars[start] == smallest) {
            start++;
        }

        while (end >= 0 && chars[end] == largest) {
            end--;
        }

        if (start <= end) {
            sb.append(smallest);
            while (start < len && chars[start] < smallest) {
                start++;
            }
            while (end >= 0 && chars[end] > largest) {
                end--;
            }
        } else {
            sb.append(largest);
            while (start < len && chars[start] > largest) {
                start++;
            }
            while (end >= 0 && chars[end] < smallest) {
                end--;
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
  Stack<Character> stack = new Stack<>();
  char[] chars = s.toCharArray();
  Arrays.sort(chars);
  for (char c : chars) {
    stack.add(c);
  }
  String sortedString = "";
  while (!stack.isEmpty()) {
    char c = stack.pop();
    sortedString += c;
  }
  return sortedString;
}

public String sortString(String s) {
String result = "";
Set<Character> chars = new HashSet<>();
for (char c : s.toCharArray()) {
chars.add(c);
}
while (chars.size() > 0) {
char min = getSmallest(chars);
result += min;
chars.remove(min);
char max = getLargest(chars);
result += max;
chars.remove(max);
}
return result;
}

private char getSmallest(Set<Character> chars) {
