public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        // pick the smallest character from s
        char smallest = s.charAt(0);
        result.append(smallest);
        s = s.substring(1);

        // pick the smallest character from s that is greater than the last appended character
        int i = 1;
        while (i < s.length() && s.charAt(i) <= result.charAt(result.length() - 1)) {
            i++;
        }
        if (i < s.length()) {
            result.append(s.charAt(i));
            s = s.substring(0, i) + s.substring(i + 1);
        }

        // pick the largest character from s
        int largestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) > s.charAt(largestIndex)) {
                largestIndex = i;
            }
        }
        result.append(s.charAt(largestIndex));
        s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);

        // pick the largest character from s that is smaller than the last appended character
        i = s.length() - 1;
        while (i >= 0 && s.charAt(i) >= result.charAt(result.length() - 1)) {
            i--;
        }
        if (i >= 0) {
            result.append(s.charAt(i));
            s = s.substring(0, i) + s.substring(i + 1);
        }
    }
    return result.toString();
}

