public int minimumInsertions(String s) {
  Stack<Character> stack = new Stack<>();
  int count = 0;

  for (int i = 0; i < s.length(); i++) {
    char current = s.charAt(i);

    if (current == '(') {
      stack.push(current);
    } else if (current == ')') {
      if (stack.isEmpty()) {
        count++;
        stack.push(current);
      } else {
        stack.pop();
      }
    }
  }

  while (!stack.isEmpty()) {
    count++;
    stack.pop();
  }

  return count;
}

