            k = k - fFibonacci.get(fFibonacci.size() - 1) - fFibonacci.get(fFibonacci.size() - 2);
        } else {
            break;
        }
    }
    return fFibonacci.size();
}

public int kthFactor(int n, int k) {
    // Find the factors of n
    int[] factors = factorize(n);

    // Check if k is in range
    if (k > factors.length) {
        return -1;
    }

    // Return the kth factor
    return factors[k - 1];
}

private int[] factorize(int n) {
    // Initialize an array to store the factors
    int[] factors = new int[n];

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if i divides n evenly
        if (n % i == 0) {
            // Add i to the array of factors
            factors.push(i);
        }
    }

    // Return the array of factors
    return factors;
}

public int kthFactor(int n, int k) {
    // Check if k is a valid input
    if (k <= 0) {
        return -1;
    }

    // Initialize a list to store the factors
    List<Integer> factors = new ArrayList<>();

    // Loop through the range of 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if i divides n evenly
        if (n % i == 0) {
            // If it does, add it to the list of factors
            factors.add(i);
        }
    }

    // Check if the list has at least k elements
    if (factors.size() < k) {
        return -1;
    }

    // Return the kth element of the list
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
if (n == 0 || n < 0 || k < 0) {
throw new IllegalArgumentException("N or K is negative.");
}
if (k > 0) {
if (n % k == 0) {
return k;
}
int temp = n;
for (int i = 2; i < Math.sqrt(temp); i++) {
if (temp % i == 0) {
temp = temp / i;
break;
}
}
if (temp != n) {
return k % (n / temp);
}
}
return -1;
}

