public String makeGood(String s) {
   Stack<Character> stack = new Stack<>();
   String res = "";
   for (int i = 0; i < s.length(); i++) {
       char c = s.charAt(i);
       if (stack.isEmpty() || stack.peek() != Character.toLowerCase(c)) {
           stack.push(c);
       } else {
           stack.pop();
       }
   }
   while (!stack.isEmpty()) {
       res = stack.pop() + res;
   }
   return res;
}

