public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] count = new int[n];
    int[] dp = new int[n];

    for (int i = 0; i < n; i++) {
        if (count[s.charAt(i) - 'a']++ == 0) {
            dp[i] = 1;
        } else {
            dp[i] = 0;
        }
    }

    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && count[s.charAt(j) - 'a'] > 1) {
            j--;
        }
        dp[i] = Math.max(dp[i], dp[j] + 1);
    }

    int max = 0;
    for (int i = 0; i < n; i++) {
        max = Math.max(max, dp[i]);
    }
    return max;
}

