public String getSmallestString(int n, int k) {
    String[] alphabet = new String[]{"a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"};
    char[] result = new char[n];
    int position = k - 1;
    for (int i = 0; i < n; i++) {
        result[i] = alphabet[position % 26];
        position /= 26;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    String smallestString = "";
    int i;
    for (i = 0; i < n; i++) {
        int lastPos = i * i;
        if (k < lastPos) {
            smallestString += (char) (lastPos - k);
            break;
        } else {
            smallestString += (char) (lastPos);
            k -= lastPos;
        }
    }
    for (; i < n; i++) {
        smallestString += (char) k;
    }
    return smallestString;
}

