    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        String numString = Integer.toString(i);
        String[] digits = numString.split("");
        boolean isStepping = true;
        for (int j = 0; j < digits.length - 1; j++) {
            if (digits[j].equals(digits[j + 1])) {
                isStepping = false;
                break;
            } else if ((Integer.parseInt(digits[j]) + 1) != Integer.parseInt(digits[j + 1])
                    && (Integer.parseInt(digits[j]) - 1) != Integer.parseInt(digits[j + 1])) {
                isStepping = false;
                break;
            }
        }
        if (isStepping) {
            steppingNumbers.add(i);
        }
    }
    steppingNumbers.sort(Comparator.naturalOrder());
    return steppingNumbers;
}

