    for (int j = 0; j < numberStr.length(); j++) {
      int digit = Character.digit(numberStr.charAt(j), 10);
      if (j == 0) {
        if (digit < 1 || digit > 9) {
          continue;
        }
      } else if (j == numberStr.length() - 1) {
        if (digit > 9 || digit < 1) {
          continue;
        }
      } else {
        int leftDigit = Character.digit(numberStr.charAt(j - 1), 10);
        int rightDigit = Character.digit(numberStr.charAt(j + 1), 10);
        if (leftDigit - digit != 1 && digit - rightDigit != 1) {
          continue;
        }
      }
    }
    steppingNumbers.add(i);
  }
  return new ArrayList<>(steppingNumbers);
}

