    if (A.length == 0) {
        return 0;
    }

    // Create a set to store the unique permutations
    Set<Integer> permutations = new HashSet<>();

    // Loop through each permutation of the array
    for (int i = 0; i < A.length; i++) {
        // Create a copy of the array
        int[] perm = A.clone();

        // Sort the array in ascending order
        Arrays.sort(perm);

        // Check if the sum of each pair of adjacent elements is a perfect square
        for (int j = 0; j < perm.length - 1; j++) {
            if (Math.sqrt(perm[j] + perm[j + 1]) % 1 == 0) {
                // If the sum is a perfect square, add the permutation to the set
                permutations.add(Arrays.toString(perm));
                break;
            }
        }
    }

    // Return the number of unique permutations
    return permutations.size();
}

