public static int minPerfectSquareSum(int n) {
    // Initialize an array to store the counts of perfect square numbers
    int[] count = new int[n+1];

    // Initialize the first element of the array to 1, since 1 is a perfect square
    count[1] = 1;

    // Iterate from 2 to n, and for each element, count the number of perfect square numbers that add up to it
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j*j <= i; j++) {
            count[i] = count[i] + count[i - j*j];
        }
    }

    // Return the minimum count of perfect square numbers
    return count[n];
}

public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    ArrayList<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if i is a perfect square
        if (isPerfectSquare(i)) {
            // Add i to the list of perfect square numbers
            perfectSquares.add(i);
        }
    }

    // Return the length of the list
    return perfectSquares.size();
}

public static boolean isPerfectSquare(int n) {
    // Check if n is a perfect square
    return (int) Math.pow(n, 0.5) == n;
}

public static int minPerfectSquareSum(int n) {
   int count = 0;
   for (int i = 1; i <= n; i++) {
       int root = (int)Math.sqrt(i);
       if (root * root == i) {
           count++;
       }
   }
   return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
  int minSquares = 0;
  for (int i = 1; i <= n; i++) {
    while (n >= i * i) {
      n -= i * i;
      minSquares++;
    }
  }
  return minSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder builder = new StringBuilder();
    for (String word : words) {
        builder.append(new StringBuffer(word).reverse().toString());
    }
    return builder.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        String reversedWord = new StringBuffer(word).reverse().toString();
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedWords = new StringBuilder();

    for (String word : words) {
        reverse(word);
        reversedWords.append(word + " ");
    }

    return reversedWords.toString().trim();
}

private static void reverse(String s) {
    char[] chars = s.toCharArray();
    for (int i = 0; i < s.length() / 2; i++) {
        char c = chars[i];
        chars[i] = chars[s.length() - i - 1];
        chars[s.length() - i - 1] = c;
    }

    s = new String(chars);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        for (int j = chars.length - 1; j >= 0; j--) {
            result.append(chars[j]);
        }
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversedWords = "";
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] charArray = word.toCharArray();
        for (int j = charArray.length - 1; j >= 0; j--) {
            reversedWords += charArray[j];
        }
        if (i < words.length - 1) {
            reversedWords += " ";
        }
    }
    return reversedWords;
}
